def canon(x):return json.dumps(x,sort_keys=True,separators=(',',':')).encode()
def sha(x):return hashlib.sha256(x).hexdigest()
def T(x):
    b=[(x>>j)&1 for j in range(x.bit_length()+2)]
    return sum((b[j]^((b[j-1] if j>=1 else 0)|(b[j-2] if j>=2 else 0)))<<j for j in range(len(b)))
def A(x):return T(x)>>2
def G(g,x):return T(x) if g=='t' else T(x)^1 if g=='u' else T(2*x+1)>>1
def gate(x):return 'u' if x%16==7 else 't' if x%16==11 else None
def F(x):
    g=gate(x);assert g is not None;return G(g,G('p',x>>2))
S='tupp';LETTERS='tup'
def omega(x,g):return int((x%16==0 and g=='t') or (x%16==1 and g=='u'))
def admissible(w):return not any(b in w for b in ['uu','ttttt','ututtu'])
def wordstate(phase,w):
    x=3 if phase=='p' else 1;pref=[x];counts=[0]*48
    for g in w:counts[3*(x%16)+LETTERS.index(g)]+=1;x=G(g,x);pref.append(x)
    return {'endpoint':x,'word_after_root':w,'prefixes':pref,'counts48':counts,'W_star':counts[0]+counts[4]}
def H(phase,w):return ''.join(S[q%4] for q in wordstate(phase,w)['prefixes'][1:])
def beta_row(xs,branches,s):
    terms=[];counts=[0]*48
    for t in range(1,s+1):
        q=xs[t-1]
        for _ in range(s-t+1):q=A(q)
        if t==s:letter=branches[t-1]
        else:
            y=xs[t]
            for _ in range(s-t-1):y=A(y)
            letter=S[y%4]
        counts[3*(q%16)+LETTERS.index(letter)]+=1
        terms.append({'birth':t,'old_prefix_mod16':q%16,'letter':letter,'cost':omega(q,letter)})
    return {'beta':counts[0]+counts[4],'terms':terms,'counts48':counts}
paths=['results/problem1/20260905_once_prescribed_zero_independent.json','results/problem1/20260905_history_synchronization_primary.json','results/problem1/20260905_born_suffix_kernel_probe.json','proofs/informal/problem1_prescribed_history_cost_pullback.md','proofs/informal/problem1_history_synchronization.md']
