M=16384;TARGET=5995;graph=[];rev=[[] for _ in range(M)];edges=[]
for q in range(M):
    row=[]
    for g in LETTERS:
        y=G(g,q)%M;row.append((g,y));rev[y].append(q);edges.append([q,g,y])
    graph.append(row)
dist=[-1]*M;dist[TARGET]=0;queue=collections.deque([TARGET])
