        if dist[q]<0:dist[q]=dist[y]+1;queue.append(q)
for q,row in enumerate(graph):
    if dist[q]<0:assert all(dist[y]<0 for _,y in row)
    else:
        assert q==TARGET or any(dist[y]==dist[q]-1 for _,y in row)
        assert all(dist[y]<0 or dist[q]<=dist[y]+1 for _,y in row)
ordinary={}
for phase,root in [('p',3),('u',1)]:
    if dist[root]<0:ordinary[phase]={'reachable':False};continue
    q=root;w=''
    while dist[q]:
        g,y=next((g,y) for g,y in graph[q] if dist[y]==dist[q]-1);w+=g;q=y
    states=[wordstate(phase,w)];branches=''
