        x=states[-1]['endpoint'];g=gate(x);assert g is not None;branches+=g
        w=H(phase,w)+g;st=wordstate(phase,w);assert st['endpoint']==F(x);states.append(st)
    assert branches=='ttuttu' and admissible(branches)
