decompositions={};letters_checked=0;full_tables=0
for label,obs in observations.items():
    phase=obs['phase'];states=obs['states'];branches=obs['branches'];xs=[st['endpoint'] for st in states]
    origin=states[0];n=len(origin['word_after_root']);rows=[]
    for s,st in enumerate(states):
        exact=wordstate(phase,st['word_after_root'])
        for k in ['endpoint','prefixes','counts48','W_star']:assert exact[k]==st[k]
