                q=origin['prefixes'][j];y=origin['prefixes'][j+1]
                for _ in range(s):q=A(q)
                for _ in range(s-1):y=A(y)
                letter=S[y%4];original_counts[3*(q%16)+LETTERS.index(letter)]+=1
                assert letter==st['word_after_root'][j];letters_checked+=1
        assert [a+b for a,b in zip(original_counts,born['counts48'])]==exact['counts48']
        direct=[0]*48
        for j in range(n,n+s):direct[3*(exact['prefixes'][j]%16)+LETTERS.index(st['word_after_root'][j])]+=1
        assert direct==born['counts48'];full_tables+=1
        rows.append({'s':s,'n':n,'W':exact['W_star'],'C':original_counts[0]+original_counts[4],**born,'next_gate':gate(xs[s]),'endpoint_hex':hex(xs[s])})
    decompositions[label]=rows
for a,w in ordinary.items():
