assert [(decompositions['cut1_'+a][1]['C'],decompositions['cut1_'+a][7]['C']) for a in ['p','u']]==[(0,2),(0,0)]
assert all(decompositions['cut1_p'][s]['counts48']==decompositions['cut1_u'][s]['counts48'] for s in range(7))
