    rows.sort(key=lambda r:tuple('tu'.index(c) for c in r['word']))
    assert rows==level['rows'];atlas.append({'length':length,'admissible_count':len(rows),'positive_words':[r['word'] for r in rows if r['oldest_cost']]})
assert atlas[-1]['positive_words']==['ttuttu','tutttu','uttttu'] and all(not a['positive_words'] for a in atlas[:-1])
